const retire=()=>{const j=json('CURRENT_CHECKPOINT.json');if(j.activeWork.current.activeExecutionSessions[0]?.driverPid===process.pid){j.activeWork.current.activeExecutionSessions=[];fs.writeFileSync('CURRENT_CHECKPOINT.json',JSON.stringify(j,null,2)+'\n');}};const early=()=>{if(!fs.existsSync(dir+'/SUPERVISOR-HANDLE.json'))retire();};process.once('exit',early);
