const result={at:new Date().toISOString(),phase,passing,source:{path:sf,sha256:hash(sf)},run,roots:phase==='tests'?roots:undefined,counts,types:types?{path:tf,sha256:hash(tf),roots:types.roots.length,files:types.sourceFiles.length,diagnostics:types.diagnosticCount}:null,wholeSuitePassing:false,normalPreviewChanged:false};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});if(passing){const accepted=fs.existsSync(af)?json(af):{};assert(!accepted[phase]);accepted[phase]={path:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json')};fs.writeFileSync(af,JSON.stringify(accepted,null,2)+'\n');}console.log(JSON.stringify({result:dir+'/RESULT.json',passing,counts,types:result.types}));process.exitCode=passing?0:1;
